import { normalizePlace } from '@travelog/core';

import manifest from '../../assets/destinations.json';

/**
 * Destination photos (Plan 53): bundled facts about each photo the owner uploaded to
 * the media bucket, so a cover knows its placeholder, size and credit offline.
 * Generated by `pnpm media:destinations` from data/destinations/destinations.csv.
 */
export interface DestinationPhoto {
  /** Key in the media bucket, e.g. "destinations/goa.jpg". */
  key: string;
  /** Place names it shows, normalised ("goa", "panaji"). */
  names: string[];
  /** Our places ids it shows ("gn:1271157"), when known. */
  placeIds: string[];
  /** Two-letter country code; a photo with no names stands for the whole country. */
  country: string | null;
  blurhash: string;
  width: number;
  height: number;
  credit: string;
  license: string;
  source: string | null;
}

export const PHOTOS = (manifest as { photos: DestinationPhoto[] }).photos;

/**
 * The photo for a trip: its exact place, else a photo named like its destination
 * ("Goa, India" → "goa"), else one for its country, else none.
 */
export function coverFor(
  trip: { destination: string | null; destinationPlaceId: string | null },
  countryCode: string | null,
  photos: readonly DestinationPhoto[] = PHOTOS,
): DestinationPhoto | null {
  if (trip.destinationPlaceId) {
    const byId = photos.find((p) => p.placeIds.includes(trip.destinationPlaceId!));
    if (byId) return byId;
  }
  const first = trip.destination?.split(',')[0]?.trim();
  if (first) {
    const name = normalizePlace(first);
    const byName = photos.find((p) => p.names.includes(name));
    if (byName) return byName;
  }
  if (countryCode) {
    const byCountry = photos.find((p) => !p.names.length && p.country === countryCode);
    if (byCountry) return byCountry;
  }
  return null;
}
